mapper.insert:
INSERT INTO PROJECT_MEMBER (
    PROJECT_ID,
    MEMBER_ID,
    ROLE
) VALUES (
    #{projectId},
    #{memberId},
    #{role}
)

mapper.delete:
DELETE FROM PROJECT_MEMBER
WHERE PROJECT_ID = #{projectId}
  AND MEMBER_ID = #{targetMemberId}
  AND ROLE = 'MEMBER'
  AND EXISTS (
      SELECT 1
      FROM PROJECT P
      INNER JOIN PROJECT_MEMBER ADMIN_PM
              ON ADMIN_PM.PROJECT_ID = P.PROJECT_ID
      WHERE P.PROJECT_ID = #{projectId}
        AND P.DELETED_AT IS NULL
        AND ADMIN_PM.MEMBER_ID = #{loginMemberId}
        AND ADMIN_PM.ROLE = 'ADMIN'
  )

mapper.select:
SELECT COUNT(*)
FROM ISSUE
WHERE PROJECT_ID = #{projectId}
  AND ASSIGNEE_ID = #{memberId}
  AND STATUS IN ('TODO', 'IN_PROGRESS')
  AND DELETED_AT IS NULL
